def get_row(lst, x):
    coordinates = []
    for row_index, row in enumerate(lst):
        # Find all column indices in the current row where the element is x
        col_indices = [col_index for col_index, value in enumerate(row) if value == x]
        # Sort these column indices in descending order
        col_indices.sort(reverse=True)
        # Add the coordinates (row_index, col_index) to the list
        coordinates.extend((row_index, col_index) for col_index in col_indices)
    return coordinates
